function planning_allocation_table(array $rows,array $model):void{ $e='ui_escape'; ?><div class="planning-table"><table><thead><tr><th>Expense / Project</th><th>Forecast</th><th>Approved Budget</th><th>Difference</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $row):$amount=$row['estimate']['amount'];$approved=$row['approved']===null?null:accounting_cents($row['approved']); ?><tr><th scope="row"><?php if($model['role']==='Admin'&&$row['eligible']&&$amount>0): ?><label class="planning-allocation"><input type="checkbox" data-planning-key="<?= $e($row['key']) ?>" checked aria-label="<?= $e('Include '.$row['account'].' / '.$row['project']) ?>"><span><?= $e($row['account']) ?></span></label><?php else: ?><?= $e($row['account']) ?><?php endif; ?><small><?= $e($row['project']) ?></small></th><td data-label="Forecast"><?= $amount===null?'Insufficient History':$e(accounting_money(accounting_decimal($amount))) ?></td><td data-label="Approved Budget"><?= $approved===null?'No allocation':$e(accounting_money(accounting_decimal($approved))) ?></td><td data-label="Difference"><?= $amount===null||$approved===null?'—':$e(accounting_money(accounting_decimal(accounting_add($amount,-$approved)))) ?></td><td data-label="Status"><span class="planning-status"><?= $row['eligible']?'Recommended':($row['estimate']['state']==='insufficient'?'Plan manually':($row['estimate']['state']==='credit_dominated'?'Credit history':($amount===0?'Zero estimate':'Not eligible'))) ?></span><details class="planning-method"><summary>Calculation</summary><p><?= $e($row['estimate']['method_label']) ?> · <?= (int)$row['estimate']['observations'] ?> complete observations<?php if($row['estimate']['mae']!==null): ?><br>Average error <?= $e(accounting_money(accounting_decimal($row['estimate']['mae']))) ?><?php endif; ?></p></details></td></tr><?php endforeach; ?></tbody></table></div><?php }
?>
<section class="planning-page"><header class="ui-page-heading"><div><h1>Planning &amp; Forecasting</h1><p>Prepare the next budget using complete recorded expense history.</p></div><a class="ui-button" href="budgets.php?month=<?= $e($month) ?>">View Budgets</a></header>
<form method="get" class="planning-controls"><label>Planning month<input type="month" name="month" value="<?= $e($month) ?>" required></label><button class="ui-button ui-button-primary">View Planning</button></form>
<?php if($error): ?><p role="alert" class="fr-error"><?= $e($error) ?></p><?php endif;if($model):$estimate=$model['overall'];$groups=['recommended'=>[],'manual'=>[],'other'=>[]];foreach($model['details'] as $row){$group=$row['eligible']&&$row['estimate']['amount']>0?'recommended':($row['estimate']['state']==='available'&&$row['estimate']['amount']===0?'other':'manual');$groups[$group][]=$row;}$heading=$month===$current?'Current Month Outlook':'Plan for '.ui_month($month);$action=$model['approved_revision_id']?'Prepare Budget Revision from Forecast':'Create '.(new DateTimeImmutable($month.'-01'))->format('F').' Budget Draft'; ?>
<section class="planning-overview"><div><p class="planning-eyebrow"><?= $e($heading) ?></p><h2><?= $estimate['amount']===null?'Insufficient History':$e($money($estimate['amount'])) ?></h2><p>Organization-wide projected expenses</p><p><?= $model['basis']?'Complete recorded history through '.$e(ui_month($model['basis'][1])).' · '.$model['complete_months'].' complete months':'No complete recorded history is available yet.' ?></p></div><dl><div><dt>Historical Average Error</dt><dd><?= $estimate['mae']===null?'Not back-tested':$e($money($estimate['mae'])) ?></dd></div><div><dt>Approved Budget</dt><dd><?= $model['approved_total']===null?'No approved budget':$e(accounting_money($model['approved_total'])) ?></dd></div><div><dt>Projected Remaining</dt><dd><?= $model['approved_total']===null||$estimate['amount']===null?'—':$e($money(accounting_add(accounting_cents($model['approved_total']),-$estimate['amount']))) ?></dd></div></dl></section>
<p class="planning-advisory">Estimates are advisory. The incomplete current month is excluded. Nothing is recorded, submitted or approved by viewing this page.</p><?php foreach($model['warnings'] as $warning): ?><p role="status"><?= $e($warning) ?></p><?php endforeach; ?>
<section class="planning-section"><h2>Recommended Allocations</h2><p>Positive eligible estimates for your next budget. <?= $e($model['coverage']) ?>.</p><?php if($groups['recommended']):planning_allocation_table($groups['recommended'],$model);else: ?><p>No positive recommendations are available. Prepare allocations manually in Budgets.</p><?php endif; ?>
<?php if($model['role']==='Admin'): ?><section class="planning-selection" aria-label="Suggested budget selection"><h3>Suggested Budget Baseline</h3><p id="planning-selection-summary" role="status"></p><p>Organization forecast: <strong><?= $e($money($estimate['amount'])) ?></strong><?php if($model['approved_total']!==null): ?> · Approved budget: <strong><?= $e(accounting_money($model['approved_total'])) ?></strong><?php endif; ?></p><p>Detailed estimates are calculated independently and may not reconcile exactly to the organization forecast. Zero estimates do not prefill an explicit budget zero.</p><?php if($model['approved_revision_id']): ?><p>A private revision will copy the effective approval, update only your selected recommendations and retain all other allocations.</p><?php endif; ?><button type="button" id="planning-create" class="ui-button ui-button-primary"><?= $e($action) ?></button><p id="planning-result" role="status"></p></section><?php endif; ?></section>
<section class="planning-section"><h2>Needs Manual Planning</h2><p>No allocation is invented for insufficient, credit-dominated or ineligible history. Existing approved amounts are shown for reference.</p><?php if($groups['manual']):planning_allocation_table($groups['manual'],$model);else: ?><p>No manual-planning exceptions in this view.</p><?php endif; ?></section>
<details class="planning-section"><summary>Other Detailed Estimates (<?= count($groups['other']) ?>)</summary><p>Zero estimates and secondary analytical detail. Enter an explicit zero only deliberately in the Budget editor.</p><?php if($groups['other']):planning_allocation_table($groups['other'],$model);else: ?><p>No other estimates.</p><?php endif; ?></details>
<details class="planning-section"><summary>Recent Expense Trend</summary><p>Recorded monthly expenses, scaled to the largest absolute amount shown. Bars show magnitude; signed amounts retain credit and refund effects.</p><div class="planning-history"><?php $peak=1;foreach($model['history'] as $point)$peak=max($peak,abs(accounting_cents($point['amount'])));foreach($model['history'] as $point):$v=accounting_cents($point['amount']); ?><div><span><?= $e(ui_month($point['month'])) ?></span><strong><?= $e(accounting_money($point['amount'])) ?></strong><span class="planning-bar" aria-hidden="true"><span style="width:<?= min(100,abs($v)/$peak*100) ?>%"></span></span></div><?php endforeach; ?></div></details>
<details class="planning-section"><summary>How this forecast was calculated</summary><p>Signed recognized expenses from complete months are used. Advances are assets on release; eligible liquidations recognize expenses. Refunds and corrections stay signed. At least three complete months are required. Methods are compared using earlier-only rolling forecasts and average absolute error.</p><p><?= $e($estimate['method_label']) ?> · <?= (int)$estimate['folds'] ?> back-test months.</p><details><summary>Technical Details</summary><p>Calculation version: <?= $e($model['version']) ?><br>Source fingerprint: <?= $e($model['fingerprint']) ?></p></details></details>
<?php if($model['role']==='Admin'): ?><script type="application/json" id="planning-data"><?= json_encode(['csrf'=>csrf_token(),'model'=>$model,'action_label'=>$action],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR) ?></script><?php endif;endif; ?></section>
